import * as T from './vendor/three.module.js';
import {launcher,guidePoint,WHEEL} from './ballistics.js';
export function createShooterMount(robot){const mount=new T.Group();mount.name='Fixed base shooter';robot.add(mount);return mount;}
function dispose(group){for(const o of [...group.children]){group.remove(o);o.traverse(c=>{c.geometry?.dispose();if(c.material)for(const m of Array.isArray(c.material)?c.material:[c.material])m.dispose();});}}
export function updateShooterMount(mechanism,settings,diameter){const key=[settings.angle,settings.height,settings.compression,diameter].join(':');if(mechanism.userData.geometryKey===key)return;mechanism.userData.geometryKey=key;dispose(mechanism);const shot=launcher(settings.angle,settings.height,settings.compression,{x:0,z:0,theta:0},diameter),{center,hoodRadius,forward}=shot,right=new T.Vector3(1,0,0),axis=new T.Quaternion().setFromUnitVectors(new T.Vector3(0,1,0),right);
for(const [radius,width,color]of [[WHEEL/2,1.25,'#202728'],[.6,1.4,'#dac250']]){const part=new T.Mesh(new T.CylinderGeometry(radius,radius,width,32),new T.MeshStandardMaterial({color,roughness:.65}));part.quaternion.copy(axis);part.position.copy(center);mechanism.add(part);}
for(const side of [-1,1]){const mount=new T.Mesh(new T.BoxGeometry(.32,3,.55),new T.MeshStandardMaterial({color:'#a4bac2',metalness:.6,roughness:.45}));mount.position.copy(center).addScaledVector(right,side*2.1);mount.position.y=4.5;mount.rotation.y=0;mechanism.add(mount);}
const vertices=[],idx=[];for(let i=0;i<=40;i++){const a=shot.hoodStart+shot.hoodSweep*i/40;for(const x of [-2,2]){const q=guidePoint(a,hoodRadius),point=center.clone().addScaledVector(right,x).addScaledVector(forward,q.u);point.y+=q.y;vertices.push(...point.toArray());}if(i<40){const j=i*2;idx.push(j,j+1,j+2,j+1,j+3,j+2);}}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(vertices,3));geo.setIndex(idx);geo.computeVertexNormals();mechanism.add(new T.Mesh(geo,new T.MeshStandardMaterial({color:'#66d5df',side:T.DoubleSide,transparent:true,opacity:.75,metalness:.3,roughness:.4})));
mechanism.add(new T.ArrowHelper(new T.Vector3(forward.x*Math.cos(shot.a),Math.sin(shot.a),forward.z*Math.cos(shot.a)),shot.origin,6,'#69d5df',1.5,.7));}
